import{_ as t,a as o}from"./chunks/ymsh_web_page.D-4fLJ6z.js";import{_ as i,o as a,c as r,a6 as n}from"./chunks/framework.mtgKxyez.js";const g=JSON.parse('{"title":"Site Guide","description":"","frontmatter":{"title":"Site Guide","outline":false},"headers":[],"relativePath":"en/home/guide.md","filePath":"en/home/guide.md"}'),s={name:"en/home/guide.md"};function l(h,e,c,d,u,p){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="site-guide" tabindex="-1">Site Guide <a class="header-anchor" href="#site-guide" aria-label="Permalink to &quot;Site Guide&quot;">​</a></h1><p>Whenever this site says &quot;robot arm&quot;, it means the two TM5S robot arms in the YMSH library.</p><div class="info custom-block"><p class="custom-block-title">Recommendation</p><p>For a better reading experience, use a tablet or computer. Students in the library can also borrow the library computers.</p></div><div class="danger custom-block"><p class="custom-block-title">Warning</p><p>This textbook is only for <strong>Taipei Municipal Yang Ming Senior High School students</strong> for learning purposes.</p><p>The contents of this textbook <strong>must not be shared outside the school in any form</strong>.</p><p>Do not give the textbook contents or the shared password to <strong>non-YMSH students</strong> or any unauthorized third party.</p></div><h2 id="lesson-levels" tabindex="-1">Lesson Levels <a class="header-anchor" href="#lesson-levels" aria-label="Permalink to &quot;Lesson Levels&quot;">​</a></h2><p>The textbook is split into three levels:</p><ul><li>Basic: for complete beginners who want to get hands-on with the robot arm fast</li><li>Intermediate: for newer competitors who want the must-have competition skills</li><li>Advanced: experience and techniques for players who want strong competition results</li></ul><p>Pick the level that fits your current skill and start from there.</p><h2 id="booking-practice" tabindex="-1">Booking Practice <a class="header-anchor" href="#booking-practice" aria-label="Permalink to &quot;Booking Practice&quot;">​</a></h2><p>The robot arms are currently managed by the library. Please ask the library director before practicing.</p><p>When using the robot arm, please be decent: put the arm and all parts back after use, and restore the environment to its original state.</p><p>If you find any damage, or if you want to buy extra end tools, tell the library director.</p><h2 id="finding-this-site" tabindex="-1">Finding This Site <a class="header-anchor" href="#finding-this-site" aria-label="Permalink to &quot;Finding This Site&quot;">​</a></h2><ul><li>Link: <a href="https://chuen666666.github.io/YMSH_TMRobot_Textbook/" target="_blank" rel="noreferrer">https://chuen666666.github.io/YMSH_TMRobot_Textbook/</a></li><li>QR Code: <img src="'+t+'" alt="QR Code" width="120px"></li><li>School website: <img src="'+o+'" alt="Where this site appears on the school website"></li></ul><h2 id="editing-the-textbook" tabindex="-1">Editing the Textbook <a class="header-anchor" href="#editing-the-textbook" aria-label="Permalink to &quot;Editing the Textbook&quot;">​</a></h2><p>This textbook is not open for public editing right now. If you find a mistake, notice that a description no longer matches the current system version, or want to suggest new content, contact the author:</p><ul><li>Discord: <a href="http://discordapp.com/users/929138508772311150" target="_blank" rel="noreferrer">chuen666666</a></li><li>LINE: <a href="https://line.me/ti/p/PIRT8GwtGk" target="_blank" rel="noreferrer">chuen666666</a></li><li>Email: <a href="mailto:chunyutsai97@gmail.com" target="_blank" rel="noreferrer">chunyutsai97@gmail.com</a></li></ul>',17)])])}const f=i(s,[["render",l]]);export{g as __pageData,f as default};
